mapper.select:
SELECT
FROM biz_product p LEFT JOIN biz_product_type pt ON pt.id = p.product_type_id AND pt.deleted = 0 WHERE p.deleted = 0
AND ( p.product_code LIKE CONCAT('%', #{keyword}, '%') OR p.product_name LIKE CONCAT('%', #{keyword}, '%') )
AND p.product_type_id = #{productTypeId}
AND p.status = #{status}
ORDER BY p.id DESC
